<?php
namespace App\Services; use App\Models\Referral; use App\Models\User; use App\Notifications\ReferralRewardNotification; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB; use Illuminate\Support\Str;
class ReferralService { public const REWARD=1000; public function codeFor(User $u):string{if($u->referral_code)return $u->referral_code;do{$c=Str::lower(Str::random(16));}while(User::where('referral_code',$c)->exists());$u->forceFill(['referral_code'=>$c])->save();return $c;} public function capture(Request $r,string $c):bool{$u=User::where('referral_code',$c)->where('is_active',true)->where('is_banned',false)->first();if(!$u)return false;$r->session()->put('referral_code',$c);return true;} public function attachFromSession(User $u,Request $r):void{$c=$r->session()->pull('referral_code');if(!$c)return;$i=User::where('referral_code',$c)->first();if(!$i||$i->id===$u->id)return;Referral::firstOrCreate(['invited_user_id'=>$u->id],['inviter_id'=>$i->id,'reward_points'=>self::REWARD]);$this->finalize($u);} public function finalize(User $u):void{if(!$u->username)return;$notice=null;DB::transaction(function()use($u,&$notice){$r=Referral::where('invited_user_id',$u->id)->lockForUpdate()->first();if(!$r||$r->rewarded_at)return;$i=User::whereKey($r->inviter_id)->lockForUpdate()->first();if(!$i)return;$i->increment('points',$r->reward_points);$r->update(['rewarded_at'=>now()]);$notice=[$i,$u->username,$r->reward_points];});if($notice)$notice[0]->notify(new ReferralRewardNotification($notice[1],$notice[2]));} }
